import os,json,subprocess
from pathlib import Path
paths={
"/srv/lowcost-europa":"/srv/projects/lowcost-europa",
"/var/lib/lowcost-europa":"/srv/projects/lowcost-europa/data",
"/var/backups/lowcost-europa":"/srv/projects/lowcost-europa/backups",
"/etc/lowcost-europa":"/srv/projects/lowcost-europa/private/systemd-env"}
out={"aliases":{},"references":{},"private_refs":{},"active_environ_refs":{},"generic_backup":{}}
for src,dst in paths.items():
 p=Path(src);out["aliases"][src]={"linked":p.is_symlink(),"resolves_canonical":p.is_symlink() and p.resolve(strict=False)==Path(dst)}
 out["references"][src]=[]
script=Path("/usr/local/sbin/project-secrets-offsite-backup")
if script.is_file():
 b=script.read_bytes()
 out["generic_backup"]={"exists":True,"references":{src:b.count(src.encode()) for src in paths},"project_specific_mentions":{n:b.count(n.encode()) for n in ("lowcost-europa","fadego","pink-iptv","telegram-robot-leads","iptvpn-bot")},"sha256_publicly_unexposed":True}
checked=0
for base in ("/etc/systemd/system","/etc/nginx","/etc/cron.d","/usr/local/bin","/usr/local/sbin","/srv/projects/lowcost-europa"):
 root=Path(base)
 if not root.is_dir():continue
 for cur,dirs,files in os.walk(root,followlinks=False):
  if len(Path(cur).relative_to(root).parts)>5:dirs[:]=[];continue
  dirs[:]=[x for x in dirs if x not in ("archive",".git",".venv","node_modules","private","data","backups","www",".cache","__pycache__","staticfiles")]
  for n in files:
   p=Path(cur)/n
   try:
    if p.is_symlink() or not p.is_file() or p.stat().st_size>120000:continue
    checked+=1
    b=p.read_bytes()
    for src in paths:
     if src.encode() in b:out["references"][src].append(str(p))
   except OSError:pass
for proc in Path("/proc").iterdir():
 if not proc.name.isdecimal() or int(proc.name) in (os.getpid(),os.getppid()):continue
 try:
  b=(proc/"environ").read_bytes()
  hits=[s for s in paths if s.encode() in b]
  for s in hits:out["active_environ_refs"].setdefault(s,[]).append((proc/"comm").read_text().strip())
 except OSError:pass
for sec in (Path("/srv/projects/lowcost-europa/private"),Path("/srv/projects/lowcost-europa/data")):
 if sec.is_dir():
  for p in sec.rglob("*"):
   try:
    if p.is_file() and not p.is_symlink() and p.stat().st_size<160000:
     b=p.read_bytes()
     for s in paths:out["private_refs"][s]=out["private_refs"].get(s,0)+b.count(s.encode())
   except OSError:pass
out["scanned_files"]=checked
print(json.dumps(out,sort_keys=True))
